import {jsPDF} from 'npm:jspdf@2.5.1';
import {createAdminClient,requireInternalSecret} from '../_shared/amazon/supabase.ts';
import {purgePickupDocuments} from '../_shared/pickupDocumentPurge.ts';
Deno.serve(async(request:Request)=>{
 if(request.method!=='POST')return new Response('Method not allowed',{status:405});
 try{requireInternalSecret(request)}catch{return new Response('Unauthorized',{status:401})}
 try{const result=await purgePickupDocuments(createAdminClient(),(created,fileId)=>{const doc=new jsPDF({unit:'mm',format:'a4',compress:true,putOnlyUsedFonts:true});doc.setCreationDate(created);doc.setFileId(fileId);return doc});return new Response(JSON.stringify(result),{status:result.ok?200:503,headers:{'Content-Type':'application/json'}})}catch{return new Response(JSON.stringify({ok:false,code:'PICKUP_PURGE_FAILED'}),{status:503,headers:{'Content-Type':'application/json'}})}
});

import {assertHumanMfa} from '../mfa.ts';
import { createClient } from 'npm:@supabase/supabase-js@2';

export type AppCaller={
  user_id:string;
  data_owner_id:string;
  role:string;
  active:boolean;
  permissions:string[]|null;
};

export function getAdminKey(){
  const secretKeys=Deno.env.get('SUPABASE_SECRET_KEYS');
  if(secretKeys){
    try{
      const parsed=JSON.parse(secretKeys);
      if(typeof parsed?.default==='string'&&parsed.default.trim())return parsed.default.trim();
    }catch{/* legacy fallback below */}
  }
  return (Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')||'').trim();
}

export function createAdminClient(){
  const url=(Deno.env.get('SUPABASE_URL')||'').trim();
  const key=getAdminKey();
  if(!url||!key)throw new Error('Configuración interna de Supabase no disponible.');
  return createClient(url,key,{auth:{persistSession:false,autoRefreshToken:false}});
}

export function requireInternalSecret(req:Request){
  const expected=getAdminKey();
  const presented=(req.headers.get('apikey')||'').trim();
  if(!expected||!presented||presented!==expected)throw new Error('Llamada interna no autorizada.');
}

export async function authenticateUser(req:Request,admin:any):Promise<AppCaller>{
  const token=(req.headers.get('Authorization')||'').replace(/^Bearer\s+/i,'').trim();
  if(!token)throw new Error('Sesión no válida.');
  await assertHumanMfa(req,false);
  const {data:userData,error:userError}=await admin.auth.getUser(token);
  if(userError||!userData?.user)throw new Error('Sesión no válida.');
  const {data:caller,error}=await admin.from('app_users')
    .select('user_id,data_owner_id,role,active,permissions')
    .eq('user_id',userData.user.id)
    .maybeSingle();
  if(error)throw error;
  if(!caller?.active)throw new Error('Tu acceso está desactivado.');
  const {data:workspace,error:workspaceError}=await admin.from('workspaces').select('status').eq('id',caller.data_owner_id).maybeSingle();
  if(workspaceError)throw workspaceError;
  if(!workspace||!['active','trialing'].includes(workspace.status))throw new Error('El acceso de tu empresa está suspendido.');
  return caller as AppCaller;
}

export async function authenticateAdminUser(req:Request,admin:any){
  const caller=await authenticateUser(req,admin);
  if(caller.role!=='admin')throw new Error('Solo un administrador puede iniciar una sincronización manual de Amazon.');
  return caller;
}

import {createClient} from 'npm:@supabase/supabase-js@2';
import {assertMfaWithClient} from './mfa-policy.ts';
export {assertBridgeMfaAllowed} from './mfa-policy.ts';

function getAdminKey(){
  try{const keys=JSON.parse(Deno.env.get('SUPABASE_SECRET_KEYS')||'{}');if(typeof keys.default==='string'&&keys.default.trim())return keys.default.trim();}catch{/* legacy fallback */}
  return (Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')||'').trim();
}
export async function assertHumanMfa(req:Request,recent=false){
  return assertMfaWithClient(req,recent,(token)=>{
    const url=(Deno.env.get('SUPABASE_URL')||'').trim();
    const key=(Deno.env.get('SUPABASE_ANON_KEY')||'').trim()||getAdminKey();
    if(!url||!key)throw new Error('MFA_UNAVAILABLE');
    // PostgREST must receive the human token even when the API key is privileged.
    return createClient(url,key,{global:{headers:{Authorization:`Bearer ${token}`}},auth:{persistSession:false,autoRefreshToken:false}});
  });
}

/** SQL is the authority for current roles, session, approved factors and recovery locks.
 * Never pass caller-provided roles or claims to this guard. */
export async function assertMfaWithClient(
  req:Request,
  recent:boolean,
  clientForToken:(token:string)=>{rpc:(name:string,args?:Record<string,unknown>)=>PromiseLike<any>},
){
  const match=/^Bearer\s+(\S+)$/i.exec((req.headers.get('Authorization')||'').trim());
  if(!match)throw new Error('Sesión no válida.');
  const {error}=await clientForToken(match[1]).rpc('security_mfa_assert',{p_recent:recent});
  if(error)throw new Error(error.message||'MFA_UNAVAILABLE');
}

/** Shared bridge secrets do not prove a human's MFA. Disable delegation while
 * enforcement is enabled until a separately verified delegation protocol exists. */
export async function assertBridgeMfaAllowed(admin:{rpc:(name:string)=>PromiseLike<any>}){
  const {data,error}=await admin.rpc('security_mfa_bridge_allowed');
  if(error||data!==true)throw new Error('MFA_BRIDGE_DELEGATION_REQUIRED');
}

import {createPickupReportDocument} from './pickupReportDocument.ts';
const bucketName='pickup-report-documents';
const sha=async(bytes:Uint8Array)=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new Uint8Array(bytes)))).map(x=>x.toString(16).padStart(2,'0')).join('');
const imageUrl=(bytes:Uint8Array)=>{let value='';for(let n=0;n<bytes.length;n+=8192)value+=String.fromCharCode(...bytes.slice(n,n+8192));return 'data:image/png;base64,'+btoa(value)};
/** No PII enters logs or responses. Disabled SQL claim is a no-op, including cleanup. */
export async function purgePickupDocuments(admin:any,makeDocument:(created:Date,fileId:string)=>any,limit=100){
 const lease=crypto.randomUUID(),bucket=admin.storage.from(bucketName);
 const {data:targets,error}=await admin.rpc('pickup_document_purge_claim',{p_lease:lease,p_limit:Math.min(100,Math.max(1,limit))});
 if(error)throw Error('PICKUP_PURGE_CLAIM_FAILED');let purged=0,failed=0;
 for(const target of targets||[]){
  try{
   const prefix=String(target.owner)+'/'+String(target.reportId)+'/';
   const owned=(path:unknown):path is string=>typeof path==='string'&&path.startsWith(prefix)&&!path.includes('..');
   if(!Array.isArray(target.paths)||target.paths.some((path:unknown)=>!owned(path)))throw Error('PICKUP_PURGE_PATH_INVALID');
   if(target.kind==='report'){
    const {data:bundle,error:readError}=await admin.rpc('pickup_document_purge_read',{p_lease:lease,p_owner:target.owner,p_report:target.reportId});
    if(readError||!bundle)throw Error('PICKUP_PURGE_READ_FAILED');
    const image=async(path:string|null)=>{if(!path)return null;if(!owned(path))throw Error('PICKUP_PURGE_PATH_INVALID');const {data,error}=await bucket.download(path);if(error||!data)throw Error('PICKUP_PURGE_READ_FAILED');return imageUrl(new Uint8Array(await data.arrayBuffer()))};
    const generatedAt=new Date(bundle.generatedAt),path=prefix+'retention/report.pdf';
    const bytes=createPickupReportDocument(bundle.report,()=>makeDocument(generatedAt,String(target.reportId).replaceAll('-','')),{generatedAt,requireStamp:!!bundle.stampPath,signatures:bundle.signatures,stampDataUrl:await image(bundle.stampPath),logoDataUrl:await image(bundle.logoPath)});
    const hash=await sha(bytes);const uploaded=await bucket.upload(path,bytes,{contentType:'application/pdf',upsert:false});
    if(uploaded.error&&!/duplicate|already exists/i.test(String(uploaded.error.message))&&String(uploaded.error.statusCode)!=='409')throw Error('PICKUP_REDACTED_UPLOAD_FAILED');
    const stored=await bucket.download(path);if(stored.error||!stored.data||await sha(new Uint8Array(await stored.data.arrayBuffer()))!==hash)throw Error('PICKUP_REDACTED_HASH_MISMATCH');
    const staged=await admin.rpc('pickup_document_purge_stage',{p_lease:lease,p_owner:target.owner,p_report:target.reportId,p_hash:hash});if(staged.error)throw Error('PICKUP_REDACTED_STAGE_FAILED');
   }
   for(let n=0;n<target.paths.length;n+=100){const {error:removeError}=await bucket.remove(target.paths.slice(n,n+100));if(removeError)throw Error('PICKUP_PURGE_STORAGE_FAILED')}
   const {error:finishError}=await admin.rpc('pickup_document_purge_finish',{p_lease:lease,p_kind:target.kind,p_owner:target.owner,p_target:target.id});if(finishError)throw Error('PICKUP_PURGE_FINISH_FAILED');purged++;
  }catch{failed++}
 }
 return {ok:failed===0,claimed:targets?.length||0,purged,failed};
}

/** Pure shared renderer: browser and Edge generate the same allowlisted document. */
export type PickupDocument={id:string;number:string;createdAt:string;createdBy:string;sender:{legalName:string;taxId:string;address:string;email:string;phone:string};items:Array<{orderId:string;orderNumber:string;channel:string;carrier:string;trackingNumber:string;packages:number}>;totalPackages:number};
export type PickupPdfSignature={carrier:string;driverName:string;identifier:string;receivedAt:string;packages:number;signatureDataUrl:string|null;redacted?:boolean};
export type PickupPdfOptions={logoDataUrl?:string|null;stampDataUrl?:string|null;generatedAt?:Date;requireStamp?:boolean;signatures?:PickupPdfSignature[]};

export function createPickupReportDocument(report: PickupDocument, createDocument: () => any, options: PickupPdfOptions = {}): Uint8Array {
  if(options.requireStamp&&!options.stampDataUrl)throw new Error('PICKUP_STAMP_REQUIRED');
  const doc = createDocument();
  const groups = new Map<string, PickupDocument['items']>();
  for (const item of report.items) {
    const carrier = item.carrier.trim() || 'Sin transportista';
    groups.set(carrier, [...(groups.get(carrier) || []), item]);
  }
  if (!groups.size) throw new Error('El informe no contiene envíos.');
  const date = new Intl.DateTimeFormat('es-ES', { timeZone: 'Europe/Madrid', dateStyle: 'short', timeStyle: 'short' });
  const generated = `${date.format(options.generatedAt ?? new Date())} (Europe/Madrid)`;
  const created = date.format(new Date(report.createdAt));
  const lines = (value: unknown, width: number): string[] => doc.splitTextToSize(String(value ?? ''), width);
  let first = true;
  for (const [carrier, items] of groups) {
    const parcels = items.reduce((sum, item) => sum + item.packages, 0);
    const signature = options.signatures?.find(item => item.carrier === carrier);
    const collected = signature?.packages ?? parcels;
    const left = 12, right = 198, bodyBottom = 274, lineHeight = 3.5, signatureHeight = signature ? 68 : 48;
    let y = 0;
    const newPage = () => {
      if (!first) doc.addPage();
      first = false;
      doc.setTextColor(32, 41, 55);
      if (options.logoDataUrl) {
        try {
          const image = doc.getImageProperties(options.logoDataUrl);
          const scale = Math.min(23 / image.width, 15 / image.height);
          doc.addImage(options.logoDataUrl, undefined as any, left, 9, image.width * scale, image.height * scale);
        } catch { /* A damaged optional logo must not prevent printing the saved receipt. */ }
      }
      const senderX = options.logoDataUrl ? 40 : left;
      doc.setFont('helvetica', 'bold'); doc.setFontSize(9);
      const nameLines = lines(`${report.sender.legalName} · NIF: ${report.sender.taxId}`, right - senderX);
      doc.text(nameLines, senderX, 12);
      const senderY = 16 + Math.max(0, nameLines.length - 1) * 3.7;
      doc.setFont('helvetica', 'normal'); doc.setFontSize(8);
      const sender = [report.sender.address, [report.sender.email, report.sender.phone].filter(Boolean).join(' · ')].filter(Boolean).join(' · ');
      const senderLines = lines(sender, right - senderX);
      doc.text(senderLines, senderX, senderY);
      const titleY = Math.max(26, senderY + 2 + senderLines.length * 3.3);
      doc.setFont('helvetica', 'bold'); doc.setFontSize(11);
      doc.text('JUSTIFICANTE DE RECOGIDA', left, titleY);
      doc.setFont('helvetica', 'normal'); doc.setFontSize(7);
      doc.text(`Generado: ${generated}`, right, titleY, {align: 'right'});
      doc.setFont('helvetica', 'bold'); doc.setFontSize(8);
      const summary = lines(`Informe ${report.number} · Transportista: ${carrier} · Creado: ${created} · Envíos: ${items.length} · Bultos: ${parcels}`, right - left - 4);
      const stripY = titleY + 3, stripHeight = summary.length * 3.5 + 3;
      doc.setFillColor(240, 243, 246); doc.rect(left, stripY, right - left, stripHeight, 'F');
      doc.text(summary, left + 2, stripY + 3.7);
      y = stripY + stripHeight + 4;
      doc.setFontSize(8);
      doc.text('Pedido · canal', left + 2, y); doc.text('Seguimiento', 77, y); doc.text('Bultos', right - 2, y, {align: 'right'});
      doc.setDrawColor(190); doc.setLineWidth(0.15); doc.line(left, y + 1.7, right, y + 1.7);
      y += 5;
    };
    newPage();
    for (let index = 0; index < items.length; index++) {
      const item = items[index];
      const channel = ({amazon: 'Amazon', shopify: 'Shopify'} as Record<string, string>)[item.channel.toLowerCase()] || item.channel;
      doc.setFont('helvetica', 'normal'); doc.setFontSize(8);
      const order = lines(`${item.orderNumber} · ${channel}`, 59);
      doc.setFont('courier', 'normal');
      const tracking = lines(item.trackingNumber || 'Sin seguimiento', 112);
      const count = Math.max(order.length, tracking.length);
      const rowHeight = count * lineHeight + 1.5;
      const isLast = index === items.length - 1;
      // The last shipment travels with the signature block, never leaving a signature-only page.
      if (rowHeight <= 180 && y + rowHeight + (isLast ? signatureHeight : 0) > bodyBottom) newPage();
      let offset = 0;
      while (offset < count) {
        let room = Math.floor((bodyBottom - y - 1.5) / lineHeight);
        if (isLast && count - offset <= room && y + (count - offset) * lineHeight + 1.5 + signatureHeight > bodyBottom) {
          const roomWithSignatures = Math.floor((bodyBottom - y - 1.5 - signatureHeight) / lineHeight);
          // Preserve a final fragment on the signature page for exceptionally long identifiers.
          room = Math.min(room, Math.max(0, count - offset - Math.max(1, roomWithSignatures)));
        }
        if (room < 1) { newPage(); continue; }
        const take = Math.min(room, count - offset);
        doc.setFont('helvetica', 'normal'); doc.setFontSize(8);
        order.slice(offset, offset + take).forEach((line, i) => doc.text(line, left + 2, y + i * lineHeight));
        doc.setFont('courier', 'normal');
        tracking.slice(offset, offset + take).forEach((line, i) => doc.text(line, 77, y + i * lineHeight));
        doc.setFont('helvetica', 'normal');
        if (!offset) doc.text(String(item.packages), right - 2, y, {align: 'right'});
        const ruleY = y + (take - 1) * lineHeight + 1.8;
        doc.setDrawColor(225); doc.setLineWidth(0.1); doc.line(left, ruleY, right, ruleY);
        y += take * lineHeight + 1.5;
        offset += take;
        if (offset < count) newPage();
      }
    }
    y += 3;
    doc.setFont('helvetica', 'bold'); doc.setFontSize(9);
    doc.text(`TOTAL RECOGIDO · ${carrier}: ${collected} bultos / ${items.length} envíos`, left, y);
    doc.setFont('helvetica', 'normal'); doc.setFontSize(8); y += 5;
    if (signature) {
      if (collected !== parcels) { doc.text(`Bultos del informe: ${parcels} bultos · Declarados en recogida: ${collected}`, left, y); y += 4; }
      const driverLines=lines(`Conductor/a: ${signature.driverName}`, right-left);
      doc.text(driverLines,left,y); y += driverLines.length*3.5+1;
      doc.text(signature.redacted?'DNI / matrícula: retirado por retención':`DNI / matrícula: ${signature.identifier}`,left,y); y += 5;
      doc.text(`Fecha y hora de recogida: ${date.format(new Date(signature.receivedAt))} (Europe/Madrid)`,left,y); y += 5;
    } else {
      doc.text('Conductor/a: __________________________________    DNI / matrícula: __________________', left, y); y += 5;
      doc.text('Fecha y hora de recogida: ________________________________________________________', left, y); y += 5;
    }
    doc.text('Firma del conductor/a', left, y); doc.text('Firma / sello del remitente', 110, y);
    y += 2; doc.setDrawColor(100); doc.setLineWidth(0.2);
    doc.rect(left, y, 60, 25); doc.rect(110, y, 60, 25);
    if (signature?.signatureDataUrl) {
      const image=doc.getImageProperties(signature.signatureDataUrl);
      const scale=Math.min(56/image.width,21/image.height),width=image.width*scale,height=image.height*scale;
      doc.addImage(signature.signatureDataUrl,'PNG',left+(60-width)/2,y+(25-height)/2,width,height);
    }
    if (signature?.redacted) { doc.setFontSize(7); doc.text('Firma retirada por retención',left+3,y+13); }
    if (options.stampDataUrl) {
      try {
        const image = doc.getImageProperties(options.stampDataUrl);
        const scale = Math.min(56 / image.width, 21 / image.height);
        const width = image.width * scale, height = image.height * scale;
        doc.addImage(options.stampDataUrl, undefined as any, 110 + (60 - width) / 2, y + (25 - height) / 2, width, height);
      } catch { if(options.requireStamp)throw new Error('PICKUP_STAMP_REQUIRED'); /* Unsigned print remains tolerant. */ }
    }
  }
  const total = doc.getNumberOfPages();
  for (let page = 1; page <= total; page++) {
    doc.setPage(page); doc.setFont('helvetica', 'normal'); doc.setFontSize(8); doc.setTextColor(100);
    doc.text(`Informe ${report.number}`, 14, 286);
    doc.text(`Página ${page} de ${total}`, 196, 286, { align: 'right' });
  }
  return new Uint8Array(doc.output('arraybuffer'));
}
